-- Certower initial schema (SQLite). IDs are UUIDv7 text generated by the app.
-- See docs/data-model.md for the diagram. Keep in sync with ../postgres.
-- Lists and JSON documents are stored as TEXT holding JSON.

CREATE TABLE organizations (
    id          TEXT PRIMARY KEY,
    slug        TEXT NOT NULL UNIQUE,
    name        TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE projects (
    id          TEXT PRIMARY KEY,
    org_id      TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    slug        TEXT NOT NULL,
    name        TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (org_id, slug)
);

-- ---------------------------------------------------------------- identity

CREATE TABLE users (
    id             TEXT PRIMARY KEY,
    email          TEXT NOT NULL UNIQUE,
    display_name   TEXT NOT NULL DEFAULT '',
    password_hash  TEXT,               -- NULL for OIDC-only users
    oidc_issuer    TEXT,
    oidc_subject   TEXT,
    is_superuser   BOOLEAN NOT NULL DEFAULT false,  -- instance admin
    disabled       BOOLEAN NOT NULL DEFAULT false,
    created_at     TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (oidc_issuer, oidc_subject)
);

-- Machine identities for CI/CD. Always project-scoped.
CREATE TABLE service_accounts (
    id          TEXT PRIMARY KEY,
    project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name        TEXT NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (project_id, name)
);

CREATE TABLE api_tokens (
    id                  TEXT PRIMARY KEY,
    service_account_id  TEXT NOT NULL REFERENCES service_accounts(id) ON DELETE CASCADE,
    token_hash          BLOB NOT NULL UNIQUE,   -- SHA-256 of the token
    expires_at          TIMESTAMP,
    last_used_at        TIMESTAMP,
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE sessions (
    id          TEXT PRIMARY KEY,
    user_id     TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash  BLOB NOT NULL UNIQUE,   -- SHA-256 of the session token
    expires_at  TIMESTAMP NOT NULL,
    created_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX sessions_expires ON sessions(expires_at);

CREATE TABLE custom_roles (
    id           TEXT PRIMARY KEY,
    org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    permissions  TEXT NOT NULL,    -- array of permission strings
    UNIQUE (org_id, name)
);

-- Exactly one subject per binding. project_id NULL = whole organization.
CREATE TABLE role_bindings (
    id                  TEXT PRIMARY KEY,
    org_id              TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    project_id          TEXT REFERENCES projects(id) ON DELETE CASCADE,
    role                TEXT NOT NULL,
    user_id             TEXT REFERENCES users(id) ON DELETE CASCADE,
    service_account_id  TEXT REFERENCES service_accounts(id) ON DELETE CASCADE,
    oidc_group          TEXT,                  -- IdP group claim value
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK ((user_id IS NOT NULL) + (service_account_id IS NOT NULL) + (oidc_group IS NOT NULL) = 1)
);
CREATE INDEX role_bindings_user ON role_bindings(user_id);
CREATE INDEX role_bindings_group ON role_bindings(oidc_group);

-- ---------------------------------------------------------------- secrets

-- Envelope encryption: value is encrypted with a per-secret DEK, the DEK is
-- wrapped by the KEK named in kek_id (local file, Vault, cloud KMS).
CREATE TABLE secrets (
    id           TEXT PRIMARY KEY,
    org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    project_id   TEXT REFERENCES projects(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    kek_id       TEXT NOT NULL,
    wrapped_dek  BLOB NOT NULL,
    ciphertext   BLOB NOT NULL,
    rotated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX secrets_name ON secrets(org_id, ifnull(project_id, ''), name);

-- ---------------------------------------------------------------- plugins

-- A configured instance of an Issuer, DNS, Deployer or Notifier plugin.
-- config is JSON validated against the plugin's schema. Secret fields hold
-- {"$secret": "<secret id>"} references, resolved only inside the server.
CREATE TABLE plugin_configs (
    id           TEXT PRIMARY KEY,
    org_id       TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    project_id   TEXT REFERENCES projects(id) ON DELETE CASCADE,  -- NULL = shared org-wide
    kind         TEXT NOT NULL CHECK (kind IN ('issuer', 'dns', 'deployer', 'notifier')),
    plugin       TEXT NOT NULL,       -- plugin Meta.Name, e.g. "acme"
    name         TEXT NOT NULL,       -- user label, e.g. "TWCA production"
    config       TEXT NOT NULL,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX plugin_configs_name ON plugin_configs(org_id, ifnull(project_id, ''), kind, name);

CREATE TABLE policies (
    project_id   TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
    rules        TEXT NOT NULL,      -- internal/policy.Policy
    updated_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- ---------------------------------------------------------------- agents & targets

CREATE TABLE agents (
    id                 TEXT PRIMARY KEY,
    project_id         TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    hostname           TEXT NOT NULL,
    os                 TEXT NOT NULL,
    version            TEXT NOT NULL,
    client_cert_fp     TEXT UNIQUE,   -- SHA-256 of the agent's mTLS cert
    enroll_token_hash  BLOB UNIQUE,  -- one-time token, NULL once used
    last_seen_at       TIMESTAMP,
    created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- Where a certificate gets installed. Either on an agent, or through a
-- server-side connector (agent_id NULL).
CREATE TABLE targets (
    id                  TEXT PRIMARY KEY,
    project_id          TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name                TEXT NOT NULL,
    deployer_config_id  TEXT NOT NULL REFERENCES plugin_configs(id),
    agent_id            TEXT REFERENCES agents(id) ON DELETE SET NULL,
    settings            TEXT NOT NULL DEFAULT '{}',  -- per-target deployer settings
    verify_endpoint     TEXT,         -- host:port to check after deploy
    created_at          TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (project_id, name)
);

-- ---------------------------------------------------------------- certificates

-- A managed certificate: the desired state that renewals keep satisfying.
CREATE TABLE certificates (
    id                 TEXT PRIMARY KEY,
    project_id         TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    name               TEXT NOT NULL,
    names              TEXT NOT NULL,              -- SANs; first is the CN
    key_type           TEXT NOT NULL,
    issuer_config_id   TEXT NOT NULL REFERENCES plugin_configs(id),
    dns_config_id      TEXT REFERENCES plugin_configs(id),
    profile            TEXT,
    key_location       TEXT NOT NULL CHECK (key_location IN ('agent', 'server')),
    renew_before_ratio REAL NOT NULL DEFAULT 0.33,  -- used when the CA has no ARI
    owner_email        TEXT,
    status             TEXT NOT NULL DEFAULT 'pending',
    created_at         TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (project_id, name)
);

CREATE TABLE certificate_targets (
    certificate_id  TEXT NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,
    target_id       TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    PRIMARY KEY (certificate_id, target_id)
);

-- One issued instance of a managed certificate.
CREATE TABLE certificate_versions (
    id               TEXT PRIMARY KEY,
    certificate_id   TEXT NOT NULL REFERENCES certificates(id) ON DELETE CASCADE,
    serial           TEXT NOT NULL,
    fingerprint      TEXT NOT NULL UNIQUE,  -- hex SHA-256 of leaf DER
    ari_cert_id      TEXT,
    not_before       TIMESTAMP NOT NULL,
    not_after        TIMESTAMP NOT NULL,
    renew_after      TIMESTAMP NOT NULL,  -- from ARI or renew_before_ratio
    chain_pem        TEXT NOT NULL,
    key_secret_id    TEXT REFERENCES secrets(id),  -- only for key_location = 'server'
    revoked_at       TIMESTAMP,
    revoke_reason    INT,
    created_at       TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX certificate_versions_renew ON certificate_versions(renew_after) WHERE revoked_at IS NULL;

CREATE TABLE deployments (
    id                  TEXT PRIMARY KEY,
    version_id          TEXT NOT NULL REFERENCES certificate_versions(id) ON DELETE CASCADE,
    target_id           TEXT NOT NULL REFERENCES targets(id) ON DELETE CASCADE,
    status              TEXT NOT NULL CHECK (status IN ('pending', 'deploying', 'verifying', 'done', 'failed', 'rolled_back')),
    rollback_state      TEXT,
    message             TEXT,
    started_at          TIMESTAMP,
    finished_at         TIMESTAMP
);
CREATE INDEX deployments_target ON deployments(target_id, finished_at DESC);

-- ---------------------------------------------------------------- jobs

CREATE TABLE jobs (
    id           TEXT PRIMARY KEY,
    project_id   TEXT REFERENCES projects(id) ON DELETE CASCADE,
    type         TEXT NOT NULL,         -- issue, deploy, scan, notify
    payload      TEXT NOT NULL,
    status       TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'waiting_manual', 'done', 'failed')),
    attempts     INT NOT NULL DEFAULT 0,
    run_after    TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    locked_by    TEXT,
    locked_until TIMESTAMP,
    last_error   TEXT,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX jobs_ready ON jobs(run_after) WHERE status = 'queued';

-- ---------------------------------------------------------------- discovery

CREATE TABLE discovery_endpoints (
    id               TEXT PRIMARY KEY,
    org_id           TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE,
    project_id       TEXT REFERENCES projects(id) ON DELETE SET NULL,
    host             TEXT NOT NULL,
    port             INT NOT NULL,
    sni              TEXT NOT NULL DEFAULT '',
    last_scanned_at  TIMESTAMP,
    last_error       TEXT,
    UNIQUE (org_id, host, port, sni)
);

CREATE TABLE discovered_certificates (
    id            TEXT PRIMARY KEY,
    endpoint_id   TEXT NOT NULL REFERENCES discovery_endpoints(id) ON DELETE CASCADE,
    fingerprint   TEXT NOT NULL,
    subject       TEXT NOT NULL,
    issuer        TEXT NOT NULL,
    names         TEXT NOT NULL,
    not_before    TIMESTAMP NOT NULL,
    not_after     TIMESTAMP NOT NULL,
    findings      TEXT NOT NULL DEFAULT '[]',  -- internal/discovery.Finding
    version_id    TEXT REFERENCES certificate_versions(id) ON DELETE SET NULL,  -- NULL = unmanaged
    first_seen_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    last_seen_at  TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (endpoint_id, fingerprint)
);

-- ---------------------------------------------------------------- audit

-- Append-only. The app role has INSERT and SELECT only.
CREATE TABLE audit_log (
    id            INTEGER PRIMARY KEY AUTOINCREMENT,
    at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    org_id        TEXT,                -- NULL for instance-level events
    project_id    TEXT,
    actor_type    TEXT NOT NULL,       -- user, service_account, agent, system
    actor_id      TEXT NOT NULL,
    action        TEXT NOT NULL,       -- e.g. cert.issue, policy.update
    object_type   TEXT NOT NULL,
    object_id     TEXT NOT NULL,
    before        TEXT,
    after         TEXT,
    source_ip     TEXT
);
CREATE INDEX audit_log_org_at ON audit_log(org_id, at DESC);

